def text(key, code='en', **values):
    return ROWS[key][CODES.index(code) if code in CODES else 1].format(**values)


def install():
    from jarvis.i18n import EXACT
    for row in ROWS.values():
        EXACT.setdefault(row[0], dict(zip(CODES[1:], row[1:])))
